// src/Components/Professor/DeliverableEvaluator.jsx
import React from 'react';
import { Card, Button, Table, Form } from 'react-bootstrap';

const DeliverableEvaluator = ({ course }) => {
  const submissions = [
    { student: 'Juan Pérez', file: 'entrega1.pdf', grade: '', comments: '' }
  ];

  return (
    <Card className="bg-dark text-white p-3 mb-4">
      <h4>📥 Evaluar Entregables - {course.name}</h4>
      <Table striped bordered hover variant="dark">
        <thead><tr><th>Estudiante</th><th>Archivo</th><th>Nota</th><th>Comentarios</th><th>Acciones</th></tr></thead>
        <tbody>
          {submissions.map((s, i) => (
            <tr key={i}>
              <td>{s.student}</td>
              <td><Button variant="light" size="sm">Descargar</Button></td>
              <td><Form.Control type="number" placeholder="Nota" /></td>
              <td><Form.Control placeholder="Observaciones" /></td>
              <td><Button variant="success" size="sm">Guardar</Button></td>
            </tr>
          ))}
        </tbody>
      </Table>
    </Card>
  );
};

export default DeliverableEvaluator;
